import{_ as e,c as t,o as i,ag as n}from"./chunks/framework.CQuhCYrb.js";const g=JSON.parse('{"title":"Pi-llm","description":"","frontmatter":{"title":"Pi-llm"},"headers":[],"relativePath":"ai-ml/pi-llm.md","filePath":"ai-ml/pi-llm.md","lastUpdated":null}'),o={name:"ai-ml/pi-llm.md"};function r(s,a,l,c,d,h){return i(),t("div",null,[...a[0]||(a[0]=[n('<h1 id="pi-llm" tabindex="-1">Pi-llm <a class="header-anchor" href="#pi-llm" aria-label="Permalink to &quot;Pi-llm&quot;">​</a></h1><h2 id="pi-language-model-project" tabindex="-1">Pi Language Model Project <a class="header-anchor" href="#pi-language-model-project" aria-label="Permalink to &quot;Pi Language Model Project&quot;">​</a></h2><h3 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h3><p>The Pi Language Model Project involves innovatively using a software decoder, a Large Language Model (LLM), and various data analysis techniques to create an offline ADS-B tracker. This system was designed to automate aircraft tracking without robust GPS, data, or upper transmission capabilities. Utilizing just a 1090 MHz antenna with line-of-sight (LOS), the system can cover most of the battlespace, allowing for monitoring aircraft in the conflict zone and identifying military flights. The lack of flights near the battlespace could indicate incoming fires or other significant tactical movements.</p><h3 id="technical-details" tabindex="-1">Technical Details <a class="header-anchor" href="#technical-details" aria-label="Permalink to &quot;Technical Details&quot;">​</a></h3><h3 id="ads-b-signal-processing" tabindex="-1">ADS-B Signal Processing <a class="header-anchor" href="#ads-b-signal-processing" aria-label="Permalink to &quot;ADS-B Signal Processing&quot;">​</a></h3><p>The project starts with the reception of ADS-B signals, which are processed using a custom software decoder. These signals provide real-time data on aircraft positions, which are crucial for the tracking and analysis conducted by the project.</p><h3 id="large-language-model-llm-integration" tabindex="-1">Large Language Model (LLM) Integration <a class="header-anchor" href="#large-language-model-llm-integration" aria-label="Permalink to &quot;Large Language Model (LLM) Integration&quot;">​</a></h3><p>After decoding, the ADS-B data logs are fed into a Large Language Model (LLM). The LLM is tasked with outputting identifiers and plotting these over time. This process involves complex data analysis, including the combination of radar data and other unspecified information to enrich the ADS-B data. This enriched data could include flight plans, ear locations, and analysis on tactics, techniques, and procedures (TTPs).</p><h3 id="data-analysis-and-visualization" tabindex="-1">Data Analysis and Visualization <a class="header-anchor" href="#data-analysis-and-visualization" aria-label="Permalink to &quot;Data Analysis and Visualization&quot;">​</a></h3><p>The system automates the tracking of aircraft by analyzing data in 10-minute intervals. It identifies military flights and assesses the tactical situation by noting the absence of flights in certain areas. The LLM prompts are designed to analyze given limitations, such as aircraft capabilities and positions, to predict their operational reach.</p><h3 id="integration-with-tactical-systems" tabindex="-1">Integration with Tactical Systems <a class="header-anchor" href="#integration-with-tactical-systems" aria-label="Permalink to &quot;Integration with Tactical Systems&quot;">​</a></h3><p>The project also explores the integration of this data with tactical systems through plugins or servers, such as IJBCP or TAK, to enhance its utility in rugged environments. Additionally, the project has considered the use of sim modems and LoRa (Long Range) technology for remote data access and integration with solar power for autonomous operation.</p><h3 id="hardware-and-software-setup" tabindex="-1">Hardware and Software Setup <a class="header-anchor" href="#hardware-and-software-setup" aria-label="Permalink to &quot;Hardware and Software Setup&quot;">​</a></h3><p>The hardware setup includes a Raspberry Pi 4 running the LLM, combined with a custom ADS-B receiver, potentially augmented with a LoRa transmitter for remote data pull. The software stack involves using an off-the-shelf LLM solution, specifically a trimmed version adapted for efficient performance on the Raspberry Pi hardware. This setup emphasizes ease of installation and maintenance, with automated server installations for quick resets if necessary.</p><h3 id="future-directions" tabindex="-1">Future Directions <a class="header-anchor" href="#future-directions" aria-label="Permalink to &quot;Future Directions&quot;">​</a></h3><p>The project has explored adding microphone and automatic transcription capabilities to extend its utility to radio communications. This development aims at further automating the analysis and intelligence-gathering processes in field operations.</p><h3 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h3><p>The Pi Language Model Project represents a significant step forward in leveraging AI and machine learning technologies for tactical and strategic advantage in military operations. By combining ADS-B data with advanced data analysis and visualization techniques, the project offers a novel approach to aircraft tracking and tactical assessment without the need for extensive hardware or high-bandwidth data connections.</p>',19)])])}const p=e(o,[["render",r]]);export{g as __pageData,p as default};
